SELECT last_restock_cohort, product_id, avg_quantity FROM (SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, product_id, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END, product_id) AS x WHERE avg_quantity < 65
